<?php
declare(strict_types=1);namespace Kios\MerchantOperations;
final class BillDraftsView {
 private static function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
 public static function money(int $n):string{return 'INR '.intdiv($n,100).'.'.str_pad((string)($n%100),2,'0',STR_PAD_LEFT);}
 public static function render(array $d,string $csrf,string $message=''):string{
 $h=fn($v)=>self::h($v);$url='/merchant.php?billing=1&merchant='.rawurlencode($d['merchant']).'&outlet='.rawurlencode($d['outlet']);$x='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bill preparation · KIOS</title><link rel="stylesheet" href="/assets/merchant-setup.css"><link rel="stylesheet" href="/assets/bill-drafts.css"><script src="/assets/bill-drafts.js" defer></script></head><body><main data-billing><header><p class="eyebrow">Private restaurant operations</p><h1>Bill preparation</h1><p class="billing-warning">DEMONSTRATION — NOT A RECEIPT OR TAX INVOICE</p><p>No payment due. No taxes, statutory fees, service charges, settlements or table release are applied.</p></header><nav aria-label="Billing sections"><a href="#selection">Table billing</a><a href="#review">Bill review</a><a href="#studio">Split studio</a><a href="#history">History</a></nav>';
 if($message)$x.='<p role="status">'.$h($message).'</p>';$x.='<section class="panel" id="selection"><h2>Choose floor, table and internal order</h2><label>Filter tables<input type="search" data-bill-search></label><div class="billing-services">';foreach($d['services']as $s){$billStatus='No bill draft';foreach($d['drafts']as $bd)if($bd['service_id']===$s['service_id'])$billStatus=$bd['status'].' / revision '.$bd['version'];$x.='<a class="billing-service" href="'.$h($url.'&service='.$s['service_id']).'">'.$h($s['floor_name'].' · '.$s['table_name']).'<strong>Internal order '.$h($s['order_id']).'</strong><span>'.$h($s['status']).' / '.$h($billStatus).'</span></a>';}$x.='</div>'.(!$d['services']?'<p>No eligible submitted internal orders. Use the existing staff POS and kitchen workflow first.</p>':'').'</section>';
 $x.='<form method="get"><input type="hidden" name="billing" value="1"><input type="hidden" name="merchant" value="'.$h($d['merchant']).'"><label>Authorized outlet<select name="outlet">';foreach($d['outlets']as$o)$x.='<option value="'.$h($o['outlet_id']).'"'.($o['outlet_id']===$d['outlet']?' selected':'').'>'.$h($o['name']).'</option>';$x.='</select></label><button>Open outlet</button></form>';
 $src=$d['source'];$old=$d['draft'];$saved=$old?json_decode($old['snapshot_json'],true):null;
 if($src){$data=$src['data'];$x.='<section class="panel" id="review"><h2>Authoritative order review</h2><p>'.$h($data['floorName'].' · '.$data['tableName']).' · Order '.$h($data['order']['order_id']).'</p><div class="billing-scroll" tabindex="0" role="region" aria-label="Order item snapshots"><table><caption>Persisted price snapshots — no client prices</caption><thead><tr><th>Product / serving</th><th>Qty</th><th>Unit price</th><th>Subtotal</th></tr></thead><tbody>';foreach($data['items']as $i)$x.='<tr><td>'.$h($i['product_name_snapshot'].' · '.$i['variant_label_snapshot'].' · '.$i['unit_snapshot']).'</td><td>'.$i['quantity'].'</td><td>'.self::money((int)$i['unit_price_paise']).'</td><td>'.self::money((int)$i['line_total_paise']).'</td></tr>';$x.='</tbody></table></div><strong>Source subtotal '.self::money($data['subtotal']).'</strong>';
 if($d['stale'])$x.='<p role="alert" class="billing-warning">STALE — the source changed. Previous calculations are historical only. Review the current order above and save an explicit new revision.</p>';
 if($saved){$x.='<div class="billing-total"><h3>'.($d['stale']?'Previous saved revision':'Saved nonfinancial preview').' · '.$h($old['status']).' · Revision '.$old['version'].'</h3><p>Discount '.self::money($saved['discount']).' · Preview total <strong>'.self::money($saved['total']).'</strong></p><ol>';foreach($saved['portions']as $v)$x.='<li>Portion '.self::money($v).'</li>';$x.='</ol><p>Portions reconcile exactly. This is never an amount authorized for payment.</p></div>';}$x.='</section>';
 if(!$old||$old['status']==='DRAFT'){$x.='<section class="panel" id="studio"><h2>Split Bill Studio</h2><form method="post" data-bill-form>';foreach(['_csrf'=>$csrf,'action'=>'billing-save','merchant'=>$d['merchant'],'outlet'=>$d['outlet'],'request'=>bin2hex(random_bytes(16)),'service'=>$data['service'],'version'=>(string)($old['version']??0),'source_hash'=>$src['hash']]as$k=>$v)$x.='<input type="hidden" name="'.$k.'" value="'.$h($v).'">';$x.='<label>Split method<select name="mode"><option value="equal"'.(($saved['mode']??'')==='equal'?' selected':'').'>Equal split</option><option value="items"'.(($saved['mode']??'')==='items'?' selected':'').'>Item quantities</option></select></label><label>People<select name="people">';for($n=1;$n<=6;$n++)$x.='<option'.(($saved['people']??1)===$n?' selected':'').'>'.$n.'</option>';$x.='</select></label><fieldset data-item-split><legend>Assign every ordered quantity exactly once</legend><p>Zero is allowed for an unused portion. All quantities must be allocated.</p>';foreach($data['items']as$i){$x.='<fieldset><legend>'.$h($i['product_name_snapshot'].' · '.$i['variant_label_snapshot']).' · ordered '.$i['quantity'].'</legend><div class="billing-allocations">';for($n=0;$n<6;$n++){$value=$saved['allocation'][(string)$i['order_item_id']][$n]??($n===0?(string)$i['quantity']:'0');$x.='<label data-person="'.$n.'">Portion '.($n+1).'<input name="allocation['.$i['order_item_id'].']['.$n.']" type="number" min="0" max="'.$i['quantity'].'" step="1" value="'.$h($value).'"></label>';}$x.='</div></fieldset>';}$x.='</fieldset><h3>Draft adjustment</h3><p>Only a fixed discount in paise is supported. No tax or fee policy is inferred. '.($d['canAdjust']?'Owner / outlet administrator authorized.':'Discount changes require an owner or outlet administrator.').'</p><label>Discount · integer paise<input name="discount" inputmode="numeric" value="'.($saved['discount']??0).'"'.(!$d['canAdjust']?' readonly':'').'></label><label>Adjustment reason<input name="reason" maxlength="240" value="'.$h($saved['reason']??'').'"></label><button>Calculate & Save Draft</button>';if($old)$x.='<button name="cancel" value="1" class="secondary">Cancel draft</button>';$x.='<p role="status" data-bill-status>Saved totals are calculated by the server. Unsaved edits are not a final preview.</p></form></section>';}
 $x.='<section class="panel" id="history"><h2>Immutable billing history</h2>';foreach($d['history']as$r){$snap=json_decode($r['snapshot_json'],true);$x.='<details><summary>Revision '.$r['version'].' · '.$h($r['operation']).' · '.gmdate('Y-m-d H:i:s',(int)$r['occurred_epoch']).' UTC</summary><p>Authorized actor '.$h($r['actor_id']).'</p><p>Recorded total '.self::money($snap['total']).' · Discount '.self::money($snap['discount']).'</p><p>'.$h($snap['reason']).'</p></details>';}$x.='</section>';}
 return $x.'</main></body></html>';
 }
}
